```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
public class LiteracyRatesAnalyzer {

    public static void main(String[] args) {

        // Load dataset into memory
        List<String[]> data = loadData("literacy_rates.csv");

        // Create a map to store the literacy rates by method
        Map<String, List<Integer>> literacyRatesByMethod = new HashMap<>();

        // Loop through the data and group the literacy rates by method
        for (String[] row : data) {
            String method = row[0];
            int literacyRate = Integer.parseInt(row[1]);

            if (!literacyRatesByMethod.containsKey(method)) {
                literacyRatesByMethod.put(method, new ArrayList<>());
            }

            literacyRatesByMethod.get(method).add(literacyRate);
        }

        // Calculate the average literacy rate for each method
        Map<String, Double> averageLiteracyRatesByMethod = new HashMap<>();

        for (String method : literacyRatesByMethod.keySet()) {
            List<Integer> literacyRates = literacyRatesByMethod.get(method);
            double average = literacyRates.stream().mapToInt(i -> i).average().getAsDouble();

            averageLiteracyRatesByMethod.put(method, average);
        }

        // Print the results
        System.out.println("Average literacy rates by method:");
        for (String method : averageLiteracyRatesByMethod.keySet()) {
            double average = averageLiteracyRatesByMethod.get(method);
            System.out.println(method + ": " + average);
        }

        // Determine the most effective method
        String mostEffectiveMethod = "";
        double highestAverage = 0.0;

        for (String method : averageLiteracyRatesByMethod.keySet()) {
            double average = averageLiteracyRatesByMethod.get(method);

            if (average > highestAverage) {
                mostEffectiveMethod = method;
                highestAverage = average;
            }
        }

        System.out.println("The most effective method is: " + mostEffectiveMethod);
    }

    private static List<String[]> loadData(String filename) {
        List<String[]> data = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filename))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] row = line.split(",");
                data.add(row);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return data;
    }

}
```
This code loads the dataset from a CSV file, groups the literacy rates by teaching method, calculates the average literacy rate for each method, and determines the most effective method based on the highest average literacy rate. You'll need to replace "literacy_rates.csv" with the filename of your dataset. Also, make sure that your dataset is in the format of "method,literacy_rate" for each row.

