public class BacteriaDetector {
    public static int detectRarestStrain(int[] resistance, double[] mortality) {
        int minResistance = Integer.MAX_VALUE;
        double maxMortality = Double.MIN_VALUE;
        int rarestStrainIndex = -1;

        for (int i = 0; i < resistance.length; i++) {
            if (resistance[i] < minResistance || (resistance[i] == minResistance && mortality[i] > maxMortality)) {
                minResistance = resistance[i];
                maxMortality = mortality[i];
                rarestStrainIndex = i;
            }
        }

        return rarestStrainIndex;
    }
}
