Here's an example of how you can modify the given Swift code to rearrange the elements of a linked list so that all even numbers come after all odd numbers:
```
class Node {
    var value: Int
    var next: Node?

    init(_ value: Int) {
        self.value = value
    }
}
func rearrangeLinkedList(head: Node?) -> Node? {
    var oddHead: Node? = nil
    var oddTail: Node? = nil
    var evenHead: Node? = nil
    var evenTail: Node? = nil
    var current: Node? = head

    while current != nil {
        if current!.value % 2 == 0 {
            if evenHead == nil {
                evenHead = current
                evenTail = current
            } else {
                evenTail!.next = current
                evenTail = current
            }
        } else {
            if oddHead == nil {
                oddHead = current
                oddTail = current
            } else {
                oddTail!.next = current
                oddTail = current
            }
        }
        current = current!.next
    }

    if oddHead == nil {
        return evenHead
    }

    oddTail!.next = evenHead
    return oddHead
}
```
This code will create two separate linked lists, one for odd values and one for even values. It will then combine these two linked lists by appending the even list to the end of the odd list.
