Yes, I can help you with that. Here's a Python program that conjugates any English verb in simple past tense based on user input:
```python
import re
def conjugate_verb(verb):
    # Define the irregular verbs
    irregular_verbs = {
        'be': {
            'singular': {
                'first': 'was',
                'second': 'were',
                'third': 'was'
            },
            'plural': {
                'first': 'were',
                'second': 'were',
                'third': 'were'
            }
        },
        'have': {
            'singular': {
                'first': 'had',
                'second': 'had',
                'third': 'had'
            },
            'plural': {
                'first': 'had',
                'second': 'had',
                'third': 'had'
            }
        },
        'do': {
            'singular': {
                'first': 'did',
                'second': 'did',
                'third': 'did'
            },
            'plural': {
                'first': 'did',
                'second': 'did',
                'third': 'did'
            }
        },
        'go': {
            'singular': {
                'first': 'went',
                'second': 'went',
                'third': 'went'
            },
            'plural': {
                'first': 'went',
                'second': 'went',
                'third': 'went'
            }
        }
    }
    # Check if the verb is irregular
    if verb in irregular_verbs:
        # Ask for subject and number
        subject = input("Enter subject (I, you, he/she/it, we, they): ")
        number = input("Enter number (singular or plural): ")

        # Conjugate the verb based on subject and number
        if number == 'singular':
            return irregular_verbs[verb]['singular'][subject.lower()]
        else:
            return irregular_verbs[verb]['plural'][subject.lower()]
    else:
        # Define the regular expression to match the verb ending
        verb_ending = re.compile(r'(.*[bcdfghjklmnpqrstvwxyz])?(.*)')
        # Match the verb ending
        match = verb_ending.match(verb)
        # Check if the verb is regular or not
        if match.group(1) in ['t', 'd']:
            verb_root = match.group(2)
            return verb_root + 'ed'
        else:
            return verb + 'ed'
# Test the function
verb = input("Enter a verb: ")
