```
package main
import "fmt"
type Product struct {
    Name     string
    Quantity int
    Price    float64
}
func main() {
    products := []Product{
        {Name: "Product 1", Quantity: 2, Price: 5.99},
        {Name: "Product 2", Quantity: 1, Price: 9.99},
        {Name: "Product 3", Quantity: 3, Price: 2.99},
