To search for a specific scientist and their most significant achievement in the given dataset using JavaScript, you can use a for loop to iterate through the array of objects and compare the inputted name to the name property of each object. Once a match is found, you can then return the corresponding achievement property.
Here's an example code:
```
function searchScientists(name) {
  for (let i = 0; i < scientists.length; i++) {
    if (scientists[i].name.toLowerCase() === name.toLowerCase()) {
      return scientists[i].achievement;
    }
  }
  return "Scientist not found";
}
console.log(searchScientists("Marie Curie")); // Output: Discovery of Radium and Polonium
```
To enable partial matching of the scientist's name, you can modify the if statement to use the `includes()` method instead of strict equality comparison.
Here's the updated code:
```
function searchScientists(name) {
  for (let i = 0; i < scientists.length; i++) {
    if (scientists[i].name.toLowerCase().includes(name.toLowerCase())) {
      return scientists[i].achievement;
    }
  }
  return "Scientist not found";
}
console.log(searchScientists("ein")); // Output: Theory of General Relativity
```
In this example, searching for "ein" will return the achievement of Albert Einstein.

